def transform(grid):
    # Copy the pattern in the final section between divider rows into every section.
    rows=len(grid); div=[i for i,r in enumerate(grid) if all(v==3 for v in r)]
    bounds=[]; start=0
    for i in div:
        bounds.append((start,i)); start=i+1
    bounds.append((start,rows))
    sr,er=bounds[-1]; pattern=[row[:] for row in grid[sr:er]]
    out=[row[:] for row in grid]
    for a,b in bounds[:-1]:
        for k in range(min(b-a,len(pattern))):
            out[a+k]=pattern[k][:]
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Uniform 3-lines are panel dividers. Repeat the pattern in the final panel.
    row_div = [i for i, row in enumerate(grid) if all(v == 3 for v in row)]
    col_div = [j for j in range(w) if all(grid[i][j] == 3 for i in range(h))]
    def sections(size, divs):
        out=[]; a=0
        for x in divs:
            out.append((a,x)); a=x+1
        out.append((a,size)); return out
    rs, cs = sections(h,row_div), sections(w,col_div)
    ra, rb = rs[-1]; ca, cb = cs[-1]
    pattern = [row[ca:cb] for row in grid[ra:rb]]
    out=[row[:] for row in grid]
    for a,b in rs:
        for c,d in cs:
            for y in range(a,b):
                for x in range(c,d):
                    py=y-a; px=x-c
                    if py < len(pattern) and px < len(pattern[py]):
                        out[y][x]=pattern[py][px]
    # Restore divider lines exactly.
    for y in row_div: out[y]=grid[y][:]
    for x in col_div:
        for y in range(h): out[y][x]=3
    return out

def transform(grid):
