    def sections(size, divs):
        out=[]; start=0
        for x in divs:
            if x > start: out.append((start, x))
            start=x+1
        if start < size: out.append((start, size))
        return out
    rs, cs = sections(h, row_div), sections(w, col_div)
    # The panel at upper-right is the pattern; repeat it in every panel.
