    out=[row[:] for row in grid]
    for a,b in rs:
        for c,d in cs:
            for y in range(a,b):
                for x in range(c,d):
                    out[y][x] = pattern[(y-a) % len(pattern)][(x-c) % len(pattern[0])]
    for y in row_div: out[y]=grid[y][:]
    for x in col_div:
        for y in range(h): out[y][x]=grid[y][x]
    return out

def transform(grid):
