def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Continue any diagonal sequence of a color (at least two cells),
    # extending each detected line in its direction until the grid edge.
    from collections import defaultdict
    pos=defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 9: pos[grid[r][c]].append((r,c))
    for color, cells in pos.items():
        for dr,dc in ((1,1),(1,-1)):
            for r,c in cells:
                # start of a run in this diagonal
                if (r-dr,c-dc) in cells: continue
                run=[]; rr,cc=r,c
                while (rr,cc) in cells:
                    run.append((rr,cc)); rr+=dr; cc+=dc
                if len(run)>=2:
                    # extend both directions, but never overwrite a non-background object
                    for sr,sc,vr,vc in ((run[0][0]-dr,run[0][1]-dc,-dr,-dc),(run[-1][0]+dr,run[-1][1]+dc,dr,dc)):
                        while 0<=sr<h and 0<=sc<w:
                            if out[sr][sc] != 9: break
                            out[sr][sc]=color
                            sr+=vr; sc+=vc
    return out

def transform(grid):
    from collections import Counter, defaultdict
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    pos = defaultdict(set)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                pos[grid[r][c]].add((r,c))
    for color, cells in pos.items():
        for dr,dc in ((1,1),(1,-1)):
            for r,c in cells:
                if (r-dr,c-dc) in cells:
                    continue
                run=[]; rr,cc=r,c
                while (rr,cc) in cells:
                    run.append((rr,cc)); rr+=dr; cc+=dc
                if len(run) < 2:
                    continue
                for sr,sc,vr,vc in ((run[0][0]-dr,run[0][1]-dc,-dr,-dc),
                                    (run[-1][0]+dr,run[-1][1]+dc,dr,dc)):
                    while 0<=sr<h and 0<=sc<w and out[sr][sc]==bg:
                        out[sr][sc]=color
                        sr+=vr; sc+=vc
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    # Every adjacent equal-color diagonal pair marks a diagonal ray. Extend
    # outward from both ends, stopping at any existing non-background cell.
    for r in range(h - 1):
        for c in range(w):
            for dc in (-1, 1):
                c2 = c + dc
                if 0 <= c2 < w and original[r][c] != bg and original[r][c] == original[r + 1][c2]:
                    color = original[r][c]
                    for rr, cc, dr, dcol in ((r, c, -1, -dc), (r + 1, c2, 1, dc)):
                        rr += dr
                        cc += dcol
                        while 0 <= rr < h and 0 <= cc < w and original[rr][cc] == bg:
                            out[rr][cc] = color
                            rr += dr
                            cc += dcol
    return out

