from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    seen=set(); q=deque()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]==0 and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==0 and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    holes={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0 and (r,c) not in seen}
    if not holes: return out
    for r,c in holes: out[r][c]=3
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 and (r,c) in seen and any(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==1 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))): out[r][c]=2
    return out

