def transform(grid):
    # Restore erased cells by extending the repeating horizontal sequence in each row.
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    for r in range(h):
        known=[c for c in range(w) if a[r][c]!=0]
        if not known: continue
        best=None
        # Find the shortest horizontal period consistent with all visible cells.
        for period in range(1,min(14,w)+1):
            buckets=[{} for _ in range(period)]
            ok=True
            for c in known:
                k=c%period
                if k in buckets[ k ] and buckets[k][k]!=a[r][c]:
                    ok=False; break
                buckets[k][k]=a[r][c]
            if ok:
                best=period; break
        if best is not None:
            for c in range(w):
                if a[r][c]==0:
                    vals=[a[r][x] for x in known if x%best==c%best]
                    if vals: a[r][c]=vals[0]
        # Remaining erased cells are inferred from the same column in adjacent rows.
    for r in range(h):
        for c in range(w):
            if a[r][c]==0:
                vals=[a[y][c] for y in range(h) if a[y][c]!=0]
                if vals: a[r][c]=min(set(vals),key=lambda v:(-vals.count(v),v))
    return a

