            if grid[r][c] != 9 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            edge = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                edge |= y == 0 or x == 0 or y == h - 1 or x == w - 1
                for ny, nx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
