def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the smallest cyclic period whose anti-diagonal classes have consistent colors.
    for period in range(1, max(h, w) + 1):
        vals = {}
        ok = True
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    k = (r + c) % period
                    if k in vals and vals[k] != color:
                        ok = False
                        break
                    vals[k] = color
            if not ok:
                break
        if ok:
            # Missing classes are filled by cycling the observed ordered pattern where needed.
            if len(vals) == period:
                return [[vals[(r+c)%period] for c in range(w)] for r in range(h)]
    # Fallback: fill using the smallest period and repeat nearest observed residue.
    period = next((p for p in range(1, max(h,w)+1) if all(len({grid[r][c] for r in range(h) for c in range(w) if grid[r][c] and (r+c)%p==k}) <= 1 for k in range(p))), 1)
    vals = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]: vals[(r+c)%period] = grid[r][c]
    return [[vals.get((r+c)%period, 0) for c in range(w)] for r in range(h)]

