def transform(grid):
    # Identify rows that are solid non-background color; these are samples of
    # a repeating row-color cycle. Infer the shortest consistent period.
    h = len(grid)
    if not h:
        return []
    w = len(grid[0])
    anchors = {}
    for r, row in enumerate(grid):
        if row and len(set(row)) == 1 and row[0] != 0:
            anchors[r] = row[0]
    if not anchors:
        return [row[:] for row in grid]
    period = h
    for p in range(1, h + 1):
        ok = True
        seen = {}
        for r, c in anchors.items():
            k = r % p
            if k in seen and seen[k] != c:
                ok = False
                break
            seen[k] = c
        if ok:
            period = p
            break
    pattern = [None] * period
    for r, c in anchors.items():
        pattern[r % period] = c
    # Fill unconstrained slots by repeating closest known pattern values.
    known = [i for i, c in enumerate(pattern) if c is not None]
    for i in range(period):
        if pattern[i] is None:
            j = min(known, key=lambda k: min((i-k) % period, (k-i) % period))
            pattern[i] = pattern[j]
    return [[pattern[r % period]] * w for r in range(h)]

