    c0=min(x for y,x,v in core); c1=max(x for y,x,v in core)
    # Include nearby detached exemplar cells (e.g. diagonal marks) around the main shape.
    pr0=max(0,r0-1); pr1=min(h-1,r1+1); pc0=max(0,c0-1); pc1=min(w-1,c1+1)
    pattern=[(y-(r0+r1)//2,x-(c0+c1)//2,grid[y][x])
