                color = next((row[j] for j in range(c-1, -1, -1) if row[j]), next((row[j] for j in range(c+1, len(row)) if row[j]), 0))
                bars.append((i, color))
        prev = -1
        for i, color in bars:
            for r in range(prev+1, i+1):
                if out[r][c] == 0: out[r][c] = color
            prev = i
    return out

def transform(grid):
    out = [row[:] for row in grid]
    # The two vertical marker columns are identified by nonzero marker cells
    # in the bottom two rows. Extend horizontal bars through their gaps upward.
    cols = [c for c in range(len(grid[0])) if grid[-1][c] != 0]
    bars_by_col = {}
    for c in cols:
        bars = []
        for r, row in enumerate(grid):
            if any(row) and row[c] == 0:
                # Use the color of the contiguous horizontal bar adjoining the gap.
                color = next((row[j] for j in range(c-1, -1, -1) if row[j]), 0)
                if not color:
                    color = next((row[j] for j in range(c+1, len(row)) if row[j]), 0)
                if color:
                    bars.append((r, color))
        prev = -1
        for r, color in bars:
            for rr in range(prev+1, r+1):
                out[rr][c] = color
            prev = r
        # Bottom marker is a short vertical ray; extend it to three rows.
        marker = grid[-1][c]
        for rr in range(max(0, len(grid)-3), len(grid)):
            if out[rr][c] == 0:
                out[rr][c] = marker
    return out

